import {loadOffers,offerWidget,mountOffers,showOffer,clearOffers} from './offers.js';
import {parseSupportedOrder} from './local-parser.js';
import {organizedReview} from './organized-review.js';
import {createExtractionSession,reviewAmounts,assertQuoteCompatibility} from './extraction-adapter.js';
import {getLocalExtractionTransport} from './extraction-runtime.js';
const extractionSession=createExtractionSession();let extractionStatus='';
function invalidateExtraction(clearReview=true){extractionSession.cancel();if(clearReview&&$('intake-reviewed'))$('intake-reviewed').checked=false;if(extractionStatus.startsWith('جاري')){extractionStatus='اتلغى الرد المتأخر لأنك عدلت المراجعة؛ تعديلاتك محفوظة.';if($('extraction-status'))$('extraction-status').textContent=extractionStatus}}
import {parseRawOrder} from './intake.js';
import {teamPanel,importsPanel} from './admin.js';
import {api,login,logout,hasSession,localMode,esc,money,normalizePhone,badge,dateLabel,copyText,download,lineAmount} from './lib.js';
import {paper,invoiceText,printInvoice,saveImages,imageBlobs} from './export.js';
if(window.self!==window.top){document.body.textContent='افتح لوحة الإدارة مباشرة في نافذة مستقلة.';throw new Error('Embedded admin page blocked')}
const $=id=>document.getElementById(id), html=s=>$('content').innerHTML=s;
let me=null,data={customers:[],invoices:[],drafts:[]},editor=null,review=null,currentInvoice=null,dirty=false,busy=false,customerCurrent=null;
let customerPageNo=0,invoicePageNo=0,customerInvoicesPage=0,customerLegacyPage=0,customerRequest=0,invoiceRequest=0,reportRequest=0;
const statuses=['draft','review','approved','sent','cancelled'];
const empty=(title,detail='')=>`<div class="card empty"><strong>${esc(title)}</strong>${esc(detail)}</div>`;
const notice=t=>`<div class="notice">${t}</div>`;
function toast(t,error=false){$('toast').textContent=t;$('toast').classList.add('show');$('toast').style.background=error?'#8c221b':'';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').classList.remove('show'),6500)}
function dialog(content){$('dialog-body').innerHTML=content;$('dialog').showModal()}
$('close-dialog').onclick=()=>$('dialog').close();
function routeTo(hash){if(dirty&&!confirm('فيه تعديلات لم تُحفظ. تسيبها؟'))return;dirty=false;location.hash=hash}
const goLink=(href,label,cls='secondary')=>`<a class="button ${cls}" href="${href}">${label}</a>`;
const title=(h,p='')=>`<div class="screen-title"><div><h1>${h}</h1><p class="muted">${p}</p></div>${me?.role!=='viewer'?goLink('#new','＋ فاتورة جديدة','primary'):''}</div>`;
function nav(){const route=(location.hash.slice(1).split('/')[0]||'dashboard');$('navigation').hidden=false;$('navigation').innerHTML=[['dashboard','الرئيسية'],['customers','العملاء'],['invoices','الفواتير'],['more','المزيد']].map(([h,t])=>`<a href="#${h}" class="${route===h?'active':''}">${t}</a>`).join('');$('session-controls').innerHTML=`<button data-action="logout">خروج</button>`}
async function refresh(){data=await api('dashboard')}
function customerCard(c){return `<article class="card list-card"><div class="row"><div><button class="linklike" data-customer="${esc(c.phone)}">${esc(c.full_name)}</button><p class="muted"><bdi>${esc(c.phone)}</bdi> · ${esc(c.area||'المنطقة غير محددة')}</p></div>${c.vip_since?'<span class="badge approved">عميل مميز</span>':''}</div><p class="muted">${c.orders_count} فاتورة · ${money(c.lifetime_value)}</p>${c.legacy_count?`<p class="muted">${c.legacy_count} تعامل قديم مراجع · ${money(c.legacy_total)}، خارج مبيعات الفواتير الجديدة</p>`:''}${me.role==='owner'?offerWidget(c.phone):''}</article>`}
function invoiceCard(i){return `<article class="card list-card"><div class="row"><div><button class="linklike" data-invoice="${i.id}">${esc(i.invoice_number)}</button><p>${esc(i.customer_snapshot.name)}</p></div><div>${badge(i.state)}<p><b>${money(i.total)}</b></p></div></div><div class="inline-meta">${esc(dateLabel(i.invoice_date))} · <bdi>${esc(i.customer_phone)}</bdi></div></article>`}
function draftCard(d){d={...d,payload:d.payload||{name:d.customer_snapshot?.name,phone:d.customer_phone,invoice_date:d.invoice_date},updated_at:d.updated_at||d.sort_at};return `<article class="card list-card"><div class="row"><div><b>${esc(d.payload.name||'عميل لم يحدد')}</b><p class="muted"><bdi>${esc(d.payload.phone||'')}</bdi> ${d.version?' · النسخة '+d.version:''}</p></div>${badge(d.state)}</div><div class="actions"><button class="secondary" data-draft="${d.id}">فتح المسودة</button>${d.state==='review'?`<button class="primary" data-review="${d.id}">مراجعة كاملة</button>`:''}</div></article>`}
function dashboard(){const t=data.summary;html(title('أهلاً بيك في ع الحلة','كل عميل له ملف واحد. وكل فاتورة تُراجع قبل الاعتماد.')+`<div class="searchrow"><input id="quick-phone" inputmode="tel" placeholder="رقم الموبايل للوصول إلى ملف العميل" aria-label="بحث برقم الموبايل"><button class="secondary" data-action="quick-find">بحث</button></div><div class="stats">${[['إجمالي العملاء',t.customers],['العملاء المميزون',t.vip],['قيمة فواتير الشهر',money(t.month_total)],['في انتظار المراجعة',t.review]].map(([k,v])=>`<div class="stat"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="split"><section><h2>في انتظار اعتماد حمدي</h2>${data.drafts.map(draftCard).join('')||empty('المراجعات خلصت')}${t.review>5?goLink('#invoices/review','كل المراجعات ('+t.review+')'):''}<h2>آخر الفواتير</h2>${data.invoices.map(invoiceCard).join('')||empty('ابدأ أول فاتورة')}</section><section><div class="card"><h2>ملخص النشاط</h2>${[['عملاء أضيفوا هذا الشهر',t.new_customers],['إجمالي الفواتير',t.invoices],['قيمة الفواتير المعتمدة',money(t.total)],['فواتير اليوم',t.today],['فواتير الشهر',t.month]].map(([k,v])=>`<div class="row"><span>${k}</span><b>${v}</b></div>`).join('')}<p class="muted">التاريخ هو التاريخ الذي حدده حمدي، وليس وقت إدخال البيانات. القيمة ليست دليل تحصيل.</p>${goLink('#reports','عرض التقارير')}</div><h2>آخر العملاء الذين تعاملوا معنا</h2>${data.customers.map(customerCard).join('')||empty('لا عملاء بعد')}<div class="notice">المسودات لا تدخل الحسابات. الاعتماد يرحّل الفاتورة مرة واحدة، والتعديل يحتاج موافقة جديدة.</div></section></div>`)}
function pager(result,key){const pages=Math.max(1,Math.ceil(result.total/result.page_size));return `<div class="row wrap pager" aria-label="صفحات النتائج"><button class="secondary" data-page-key="${key}" data-page="${result.page-1}" ${result.page<=0?'disabled':''}>السابق</button><span role="status">صفحة ${result.page+1} من ${pages} · ${result.total} نتيجة</span><button class="secondary" data-page-key="${key}" data-page="${result.page+1}" ${(result.page+1)*result.page_size>=result.total?'disabled':''}>التالي</button></div>`}
function debounceSearch(fn){let timer;return()=>{clearTimeout(timer);timer=setTimeout(()=>fn().catch(e=>toast(e.message,true)),220)}}
function bindListSearch(ids,key,fn){const delayed=debounceSearch(fn);for(const id of ids)$(id).oninput=()=>{if(key==='customers')++customerRequest;else ++invoiceRequest;$(key==='customers'?'customer-results':'invoice-results').innerHTML=empty('جارٍ البحث...');delayed()}}
function customers(){html(title('العملاء','بحث برقم الهاتف أو الاسم أو المنطقة. بدون دمج تلقائي للأرقام المختلفة.')+`<div class="actions">${me.role!=='viewer'?'<button class="secondary" data-action="new-customer">＋ إضافة عميل</button>':''}${me.role==='owner'?goLink('#customers','اقتراحات العملاء وواتساب'):''}</div><div class="searchrow"><input id="customer-search" placeholder="ابحث بالاسم أو الهاتف أو المنطقة" aria-label="بحث العملاء"><select id="customer-sort" aria-label="ترتيب العملاء"><option value="latest">آخر تعامل</option><option value="most">الأكثر طلبًا</option><option value="least">الأقل طلبًا</option><option value="value">أعلى إجمالي</option><option value="new">الأحدث إضافة</option></select><select id="customer-filter" aria-label="تصفية العملاء"><option value="all">كل العملاء</option><option value="vip">عملاء مميزون</option><option value="new">أضيفوا هذا الشهر</option></select></div><div id="customer-results"></div>`);customerPageNo=0;renderCustomers().catch(e=>toast(e.message,true));bindListSearch(['customer-search','customer-sort','customer-filter'],'customers',async()=>{if(!$('customer-search'))return;customerPageNo=0;await renderCustomers()})}
async function renderCustomers(){const request=++customerRequest;const result=await api('customer_list',{page:customerPageNo,query:$('customer-search').value,sort:$('customer-sort').value,filter:$('customer-filter').value});if(request!==customerRequest||!$('customer-results'))return;$('customer-results').innerHTML=(result.rows.map(customerCard).join('')||empty('لا توجد نتائج','راجع الرقم أو غيّر التصفية.'))+pager(result,'customers')}
async function customerPage(phone){const requestedHash=location.hash;const detail=await api('customer_detail',{phone});const c=detail.customer;if(!c){html(empty('لا يوجد عميل بهذا الرقم'));return}const legacy=await api('legacy_customer',{phone:c.phone});customerCurrent=c;const stats=c;customerInvoicesPage=0;customerLegacyPage=0;const invoiceResult=await api('invoice_list',{phone:c.phone,page:0});const list=invoiceResult.rows;if(location.hash!==requestedHash)return;customerCurrent=c;html(`<a class="back" href="#customers">العملاء ←</a><div class="screen-title"><div><h1>${esc(c.full_name)}</h1><bdi>${esc(c.phone)}</bdi> ${c.vip_since?'<span class="badge approved">عميل مميز</span>':''}</div></div><div class="actions">${me.role!=='viewer'?`<button class="primary" data-new-for="${esc(c.phone)}">＋ فاتورة لهذا العميل</button><button class="secondary" data-edit-customer="${esc(c.phone)}">تعديل البيانات</button>`:''}${me.role==='owner'?`<button class="plain" data-extra-phone="${esc(c.phone)}">إضافة رقم بتأكيد</button>`:''}</div><div class="stats"><div class="stat"><span>الفواتير المعتمدة</span><strong>${stats?.orders_count||0}</strong></div><div class="stat"><span>إجمالي فواتير النظام</span><strong>${money(stats?.lifetime_value)}</strong></div><div class="stat"><span>تعاملات قديمة مراجعة</span><strong>${stats?.legacy_count||0}</strong></div><div class="stat"><span>قيمة التاريخ المراجع</span><strong>${money(stats?.legacy_total)}</strong></div><div class="stat"><span>أول تعامل</span><p>${dateLabel(stats?.first_transaction)}</p></div><div class="stat"><span>آخر تعامل</span><p>${dateLabel(stats?.last_transaction)}</p></div></div>${me.role==='owner'?offerWidget(c.phone):''}<div class="split"><section><h2>كل الفواتير</h2><div id="customer-invoice-results">${list.map(x=>x.kind==='draft'?draftCard(x):invoiceCard(x)).join('')||empty('لا توجد فواتير بعد')}${pager(invoiceResult,'customer-invoices')}</div><h2>تعاملات قديمة تمت مراجعتها</h2><div id="customer-legacy-results">${legacy.rows.map(l=>`<article class="card"><b>طلب مصدر ${esc(l.source_id)}</b><p class="muted">${esc(dateLabel(l.source_date))} · ${money(l.recorded_total)}</p><p class="muted">سجل تاريخي مراجع، ليس فاتورة جديدة ولا ترحيل مبيعات إضافي.</p></article>`).join('')||'<p class="muted">لا سجلات تاريخية مرتبطة بعد.</p>'}${pager(legacy,'customer-legacy')}</div></section><section><div class="card"><h2>البيانات والعناوين</h2><p>${esc(c.governorate)} · ${esc(c.area)}</p><p>${esc(c.address)}</p><p class="muted">${esc(c.delivery_notes)}</p><details><summary>العناوين السابقة</summary>${detail.addresses.map(a=>`<p>${esc(a.address)}</p>`).join('')}</details><details><summary>أرقام مرتبطة بتأكيد</summary>${detail.phones.map(p=>`<p><bdi>${esc(p.phone)}</bdi>${p.is_primary?' · أساسي':' · إضافي'}</p>`).join('')}</details></div><div class="card"><h2>ملاحظات خاصة</h2><p>${esc(c.private_notes||'لا توجد ملاحظات.')}</p><p class="muted">لا تظهر على رابط الفاتورة.</p></div></section></div>`)}
function customerForm(c={}){dialog(`<h2>${c.phone?'تعديل بيانات العميل':'إضافة عميل'}</h2><form id="customer-form"><label for="c-phone">رقم الموبايل الأساسي</label><input id="c-phone" name="phone" type="tel" value="${esc(c.phone||'')}" ${c.phone?'readonly':''} required><p class="muted">لا نغير هوية العميل أو ندمج رقمين من هذه الشاشة.</p><label for="c-name">الاسم</label><input id="c-name" name="name" value="${esc(c.full_name||'')}" required><div class="grid"><div><label for="c-gov">المحافظة</label><input id="c-gov" name="governorate" value="${esc(c.governorate||'')}"></div><div><label for="c-area">المنطقة</label><input id="c-area" name="area" value="${esc(c.area||'')}"></div></div><label for="c-address">العنوان</label><textarea id="c-address" name="address">${esc(c.address||'')}</textarea><label for="c-delivery">ملاحظات توصيل</label><input id="c-delivery" name="delivery_notes" value="${esc(c.delivery_notes||'')}"><label for="c-private">ملاحظات خاصة</label><textarea id="c-private" name="private_notes">${esc(c.private_notes||'')}</textarea><button class="primary full" type="submit">حفظ العميل</button></form>`);$('customer-form').onsubmit=async e=>{e.preventDefault();await safely(async()=>{const p=Object.fromEntries(new FormData(e.target));if(!normalizePhone(p.phone))throw new Error('راجع رقم الموبايل كاملًا');const existing=await api('customer_detail',{phone:p.phone});if(existing.customer&&!c.phone){$('dialog').close();routeTo('customer/'+encodeURIComponent(existing.customer.phone));toast('الرقم موجود، اتفتح ملف العميل السابق');return}const saved=await api('customer_save',p);$('dialog').close();await refresh();routeTo('customer/'+encodeURIComponent(saved.phone));toast('اتحفظ ملف العميل')})}}
function newEditor(p={}){extractionSession.cancel();extractionStatus='';editor={id:null,version:null,payload:{name:'',phone:'',governorate:'',area:'',address:'',delivery_notes:'',invoice_date:'',delivery_date:'',items:[{name:'',quantity:1,unit:'',unit_price:0}],delivery_fee:0,discount:0,notes:'',...p}};dirty=false;drawEditor()}
function lineEditor(x,k){return `<div class="line-editor" data-line="${k}"><div class="row"><b>الصنف ${k+1}</b><button class="plain" data-remove-line="${k}" type="button" aria-label="إزالة الصنف ${k+1}">إزالة</button></div><div class="fields"><div><label for="item-name-${k}">الصنف</label><input id="item-name-${k}" data-key="name" value="${esc(x.name)}" required></div><div><label for="item-qty-${k}">الكمية</label><input id="item-qty-${k}" data-key="quantity" type="number" min="0.001" step="0.001" value="${esc(x.quantity)}" required></div><div><label for="item-unit-${k}">الوحدة</label><input id="item-unit-${k}" data-key="unit" value="${esc(x.unit)}" placeholder="كيلو / قطعة" required></div><div><label for="item-price-${k}">سعر الوحدة</label><input id="item-price-${k}" data-key="unit_price" type="number" min="0" step="0.01" value="${esc(x.unit_price)}" required></div></div><div class="line-total">إجمالي الصنف: <span data-total-line="${k}">${money(lineAmount(x.quantity,x.unit_price))}</span></div></div>`}
function drawEditor(){const p=editor.payload;if(editor.editorView==='manual'||(editor.id&&!p.source_intake)||(!p.source_intake&&[p.name,p.phone,p.address].some(x=>String(x||'').trim())))return drawManualEditor();if(!p.source_intake)return drawPaste();return drawOrganizedEditor()}
function drawPaste(){html(`<div class="screen-title"><div><h1>الصق رسالة العميل</h1><p class="muted">تطلع لك مسودة مرتبة للمراجعة فورًا. مش محتاج تملا خانات قبل ما تشوف الطلب.</p></div></div><section class="card"><label for="raw-message">رسالة العميل كما وصلتك</label><textarea id="raw-message" rows="8" placeholder="الصق الرسالة هنا"></textarea><button type="button" class="primary full" id="parse-message">رتّب واعرض الفاتورة</button><p class="muted">الاستخراج محدود بالصياغات الواضحة. المجهول يفضل ظاهرًا للمراجعة، دون تخمين سعر أو تاريخ أو هوية.</p></section><details class="card"><summary>إدخال يدوي بدل الرسالة</summary><button type="button" class="secondary" id="manual-entry">فتح الإدخال اليدوي</button></details>`);$('parse-message').onclick=parseMessage;$('manual-entry').onclick=()=>{editor.editorView='manual';drawEditor()};$('raw-message').oninput=()=>{dirty=true}}
function drawOrganizedEditor(){const p=editor.payload,source=p.source_intake;html(`<div class="screen-title"><div><span class="eyebrow">${editor.id?'مسودة محفوظة · النسخة '+editor.version:'مسودة من رسالة العميل'}</span><h1>راجع الطلب المرتب</h1><p class="muted">دي المراجعة نفسها؛ اضغط السطر لو محتاج تعديل. الناقص لا يمنع عرض الطلب، لكنه يمنع اعتماده.</p></div></div><div id="extraction-status" role="status">${extractionStatus?notice(extractionStatus):''}</div><form id="invoice-editor" novalidate>${organizedReview(p,{esc,money,dateLabel,lineAmount})}${(source.phone_candidates||[]).length>1&&!source.fields?.phone?`<section class="card"><p>في الرسالة أكثر من رقم. اختر الأساسي دون دمج:</p><div class="actions">${source.phone_candidates.map(n=>`<button class="secondary" type="button" data-intake-phone="${esc(n)}"><bdi>${esc(n)}</bdi></button>`).join('')}</div></section>`:''}${(source.additional_phones||[]).length?`<section class="card"><h2>أرقام إضافية كما وردت</h2>${source.additional_phones.map(n=>`<p><bdi>${esc(n)}</bdi> · رقم إضافي، لم يُدمج أو يُربط تلقائيًا</p>`).join('')}</section>`:''}${source.issues?.length?`<section class="card"><h2>نقاط تحتاج مراجعة</h2>${source.issues.map(x=>`<p>${esc(x)}</p>`).join('')}</section>`:''}${source.conflicts?.filter(k=>k!=='phone').length?notice('توجد بيانات متعارضة في الأصل. راجعها وحدد الصحيح قبل الاعتماد.'):''}${source.unparsed_lines?.length?`<section class="card"><h2>جزء من الرسالة يحتاج مراجعتك</h2><pre class="source-json">${esc(source.unparsed_lines.join('\n'))}</pre><p class="muted">ظاهر كما كُتب. انقل المطلوب للملاحظات أو أضفه كصنف؛ لم نخمن معناه.</p></section>`:''}<details class="card" id="raw-source"><summary>الرسالة الأصلية</summary><label for="raw-message">النص الأصلي للطلب، للإدارة فقط</label><textarea id="raw-message">${esc(source.raw_text)}</textarea><button class="secondary full" type="button" id="parse-message">إعادة ترتيب الرسالة</button><p class="muted">إعادة الترتيب تستبدل التعديلات اليدوية. الأصل لا يظهر في رابط العميل.</p></details><section class="card"><div class="check"><input id="intake-reviewed" type="checkbox" ${source.reviewed?'checked':''}><label for="intake-reviewed">راجعت الطلب والرسالة كلها، وأكدت الرقم ونوع السعر (إجمالي الصنف أو سعر الوحدة) والسطور غير المفهومة والتفاصيل الناقصة.</label></div><div class="actions"><button type="button" class="secondary" data-action="save-draft">حفظ كمسودة</button><button class="primary" type="submit">تأكيد المراجعة</button></div><p class="muted">الحفظ كمسودة لا يرحّل للحسابات. الاعتماد النهائي لحمدي بعد المراجعة.</p></section></form>`);$('invoice-editor').oninput=e=>{dirty=true;invalidateExtraction(false);if(e.target.id==='raw-message'||(editor.payload.source_intake?.version===2&&e.target.id!=='intake-reviewed'))$('intake-reviewed').checked=false;updateTotals()};$('invoice-editor').onsubmit=e=>{e.preventDefault();for(const field of $('invoice-editor').querySelectorAll(':invalid')){let node=field.parentElement;while(node&&node!==$('invoice-editor')){if(node.tagName==='DETAILS')node.open=true;node=node.parentElement}}safely(()=>saveDraft(true))};$('parse-message').onclick=parseMessage;$('add-line').onclick=()=>{readEditor();invalidateExtraction();editor.payload.items.push({name:'',quantity:'',unit:'',unit_price:''});dirty=true;drawEditor()};document.querySelectorAll('[data-intake-done]').forEach(b=>b.onclick=()=>{readEditor();drawEditor()});document.querySelectorAll('[data-intake-phone]').forEach(b=>b.onclick=()=>{readEditor();invalidateExtraction();editor.payload.phone=b.dataset.intakePhone;dirty=true;drawEditor()});updateTotals()}
function drawManualEditor(){const p=editor.payload;html(`<div class="screen-title"><div><span class="eyebrow">${editor.id?'مسودة محفوظة · النسخة '+editor.version:'فاتورة جديدة'}</span><h1>جهز الفاتورة</h1><p class="muted">مسودة فقط، لن تدخل الحسابات حتى يعتمدها حمدي.</p></div></div><div class="steps"><span class="active">١. العميل والأصناف</span><span>٢. مراجعة كاملة</span><span>٣. اعتماد وإرسال</span></div>${p.base_invoice_version?notice('هذه مراجعة لفاتورة معتمدة. الحسابات تظل على النسخة السابقة حتى الاعتماد الجديد.'):''}<form id="invoice-editor"><section class="card"><h2>ابدأ برسالة العميل</h2><p class="muted">الصق الطلب كما وصلك. نستخرج الواضح للمراجعة، والباقي يظل ظاهرًا دون تخمين.</p><label for="raw-message">النص الأصلي للطلب</label><textarea id="raw-message" placeholder="الاسم: ...&#10;الموبايل: ...&#10;العنوان: ...&#10;٢ كيلو ورق عنب&#10;نص كيلو كوسة">${esc(p.source_intake?.raw_text||'')}</textarea><button class="primary full" id="parse-message" type="button">ترتيب الطلب للمراجعة</button><p class="muted">لا نحفظ نهائيًا ولا نرسل شيئًا. التاريخ يحدده حمدي، والسعر الناقص يظل فارغًا. الصور تُراجع يدويًا، لا يوجد استخراج آلي للصور هنا.</p>${p.source_intake?`<div class="notice">الأصل محفوظ مع المسودة للإدارة فقط، ولا يظهر في رابط العميل. ${p.source_intake.conflicts?.length?'توجد حقول متعارضة تحتاج اختيارًا صريحًا.':'راجع الحقول المستخرجة أدناه.'}</div>${(p.source_intake.phone_candidates||[]).length>1?`<p>اختر رقم العميل الأساسي بعد المراجعة:</p><div class="actions">${p.source_intake.phone_candidates.map(n=>`<button type="button" class="secondary" data-intake-phone="${esc(n)}"><bdi>${esc(n)}</bdi></button>`).join('')}</div>`:''}${p.source_intake.unparsed_lines?.length?`<details open><summary>سطور تحتاج مراجعتك (${p.source_intake.unparsed_lines.length})</summary><pre class="source-json">${esc(p.source_intake.unparsed_lines.join('\n'))}</pre></details>`:''}<div class="check"><input id="intake-reviewed" type="checkbox" ${p.source_intake.reviewed?'checked':''}><label for="intake-reviewed">راجعت النص كله، ونقلت المطلوب من السطور غير المستخرجة، وأكدت هوية العميل والتفاصيل الناقصة.</label></div>`:''}</section><section class="card"><h2>العميل والتوصيل</h2><div class="grid"><div><label for="f-phone">رقم الموبايل *</label><input id="f-phone" name="phone" class="phone-field" inputmode="tel" value="${esc(p.phone)}" required><button class="secondary" data-action="lookup-customer" type="button">فتح بيانات الرقم الموجود</button></div><div><label for="f-name">اسم العميل *</label><input id="f-name" name="name" value="${esc(p.name)}" required></div><div><label for="f-gov">المحافظة</label><input id="f-gov" name="governorate" value="${esc(p.governorate)}"></div><div><label for="f-area">المنطقة</label><input id="f-area" name="area" value="${esc(p.area)}"></div></div><label for="f-address">العنوان بالتفصيل *</label><textarea id="f-address" name="address" required>${esc(p.address)}</textarea><label for="f-delivery-notes">ملاحظات التوصيل</label><input id="f-delivery-notes" name="delivery_notes" value="${esc(p.delivery_notes)}"><div class="grid"><div><label for="f-date">التاريخ الذي حدده حمدي *</label><input id="f-date" name="invoice_date" type="date" value="${esc(p.invoice_date)}" required><p class="muted">هذا التاريخ يظهر على الفاتورة ويُستخدم في الحسابات. لا نختاره تلقائيًا.</p></div><div><label for="f-delivery-date">موعد توصيل إضافي، اختياري</label><input id="f-delivery-date" name="delivery_date" type="date" value="${esc(p.delivery_date||'')}"></div></div></section><section class="card"><h2>الأصناف والأسعار</h2><p class="muted">اكتب السعر المتفق عليه وراجعه. هذه الشاشة لا تغير المنيو أو أسعاره.</p><div id="line-items">${p.items.map(lineEditor).join('')}</div><button class="secondary full" id="add-line" type="button">＋ إضافة صنف</button></section><section class="card"><h2>الحساب النهائي</h2><div class="grid"><div><label for="f-fee">التوصيل</label><input id="f-fee" name="delivery_fee" type="number" min="0" step="0.01" value="${p.delivery_fee}" required></div><div><label for="f-discount">الخصم</label><input id="f-discount" name="discount" type="number" min="0" step="0.01" value="${p.discount}" required></div></div><label for="f-notes">ملاحظات تظهر على الفاتورة</label><textarea id="f-notes" name="notes">${esc(p.notes)}</textarea><div id="editor-totals"></div></section><div class="sticky-actions"><div class="row"><button class="secondary" type="button" data-action="save-draft">حفظ كمسودة</button><button class="primary" type="submit">عرض المراجعة الكاملة</button></div></div></form>`);$('invoice-editor').oninput=()=>{dirty=true;updateTotals()};$('invoice-editor').onsubmit=e=>{e.preventDefault();safely(()=>saveDraft(true))};$('add-line').onclick=()=>{readEditor();invalidateExtraction();editor.payload.items.push({name:'',quantity:1,unit:'',unit_price:0});dirty=true;drawEditor()};$('parse-message').onclick=parseMessage;document.querySelectorAll('[data-intake-phone]').forEach(b=>b.onclick=()=>{$('f-phone').value=b.dataset.intakePhone;dirty=true;updateTotals()});$('f-phone').onblur=()=>autoFillCustomer().catch(e=>toast(e.message,true));updateTotals()}
async function autoFillCustomer(){const entered=$('f-phone')?.value;if(!normalizePhone(entered)||!editor)return;const result=await api('customer_detail',{phone:entered});if(!$('f-phone')||$('f-phone').value!==entered||!result.customer)return;const c=result.customer;const map={'f-name':c.full_name,'f-address':c.address,'f-gov':c.governorate,'f-area':c.area,'f-delivery-notes':c.delivery_notes};let changed=false;for(const [id,value]of Object.entries(map)){if(!$(id).value&&value){$(id).value=value;changed=true}}if(changed){dirty=true;readEditor();toast('الرقم موجود. اتملت الحقول الفاضية من ملف العميل، راجع العنوان قبل الاعتماد.')}}
function readEditor(){if(!$('invoice-editor'))return;const fields=Object.fromEntries(new FormData($('invoice-editor')));const items=[...document.querySelectorAll('[data-line]')].map((el,index)=>({...editor.payload.items[index],...Object.fromEntries([...el.querySelectorAll('[data-key]')].map(e=>[e.dataset.key,['quantity','unit_price'].includes(e.dataset.key)?(e.value===''?'':Number(e.value)):e.value.trim()]))}));editor.payload={...editor.payload,...fields,delivery_fee:fields.delivery_fee===''?'':Number(fields.delivery_fee),discount:fields.discount===''?'':Number(fields.discount),items};if(editor.payload.source_intake&&$('intake-reviewed'))editor.payload.source_intake.reviewed=$('intake-reviewed').checked}
function totals(p){const cents=p.items.reduce((s,x)=>s+Math.round(lineAmount(x.quantity,x.unit_price)*100),0),subtotal=cents/100;return {...p,subtotal,total:(cents+Math.round(Number(p.delivery_fee)*100)-Math.round(Number(p.discount)*100))/100}}
function updateTotals(){readEditor();if(editor.payload.source_intake?.version===2){const r=reviewAmounts(editor.payload);$('editor-totals').innerHTML=`${r.subtotal!==null?`<div class="row"><span>قيمة الأصناف حسب السطور</span><b>${money(r.subtotal)}</b></div>`:notice('قيمة الأصناف غير مكتملة')}${r.total!==null?`<div class="row grand"><span>الإجمالي</span><b>${money(r.total)}</b></div>`:notice('الإجمالي غير مكتمل؛ التوصيل أو الخصم أو مطابقة السطور يحتاج مراجعة.')}${r.issues.map(x=>notice(x)).join('')}`;return}const p=totals(editor.payload),incomplete=editor.payload.items.some(x=>x.quantity===''||x.unit_price==='')||editor.payload.delivery_fee===''||editor.payload.discount==='';if(incomplete){$('editor-totals').innerHTML=notice('الحساب غير مكتمل. أكد أسعار الوحدات والتوصيل والخصم، واكتب صفرًا صراحةً إن لم توجد رسوم أو خصم.');editor.payload.items.forEach((x,k)=>{const el=document.querySelector(`[data-total-line="${k}"]`);if(el)el.textContent=x.quantity===''||x.unit_price===''?'يحتاج سعرًا وكمية مؤكدين':money(lineAmount(x.quantity,x.unit_price))});return}$('editor-totals').innerHTML=`<div class="totals"><div class="row"><span>قيمة الأصناف</span><b>${money(p.subtotal)}</b></div><div class="row grand"><span>الإجمالي</span><b>${money(p.total)}</b></div></div>`;p.items.forEach((x,k)=>{const el=document.querySelector(`[data-total-line="${k}"]`);if(el)el.textContent=money(lineAmount(x.quantity,x.unit_price))})}
function parseMessageLocal(){try{const raw=$('raw-message').value;if(!raw.trim())throw Error('الصق رسالة العميل أولًا');if((editor.id||$('f-name')?.value.trim()||$('f-phone')?.value.trim()||$('f-address')?.value.trim()||[...document.querySelectorAll('[data-key=name]')].some(x=>x.value.trim()))&&!confirm('ترتيب الرسالة سيستبدل حقول الطلب الحالية باستخراج جديد للمراجعة. تكمل؟'))return;readEditor();const parsed=parseSupportedOrder(raw,normalizePhone);editor.payload={...editor.payload,name:'',phone:'',address:'',governorate:'',area:'',delivery_date:'',notes:'',delivery_notes:'',...parsed.fields,delivery_fee:parsed.fields.delivery_fee??'',discount:parsed.fields.discount??'',items:parsed.items.length?parsed.items:[{name:'',quantity:'',unit:'',unit_price:''}],source_intake:{...parsed,version:2,extraction_mode:'local_rules',reviewed:false}};delete editor.editorView;dirty=true;drawEditor()}catch(e){toast(e.message,true)}}
async function parseMessage(){const before=editor?.payload.source_intake;parseMessageLocal();const source=editor?.payload.source_intake;if(!source||source===before)return;const transport=localMode?getLocalExtractionTransport():null;if(!transport)return;const raw=source.raw_text;extractionStatus='جاري اختبار ترتيب الرسالة محليًا؛ لم نتصل بمزود حقيقي.';if($('extraction-status'))$('extraction-status').textContent=extractionStatus;try{const result=await extractionSession.run(raw,{transport,normalizePhone,currentSource:()=>$('raw-message')?.value??''});if(result.status!=='ready')return;const parsed=result.parsed;editor.payload={...editor.payload,name:'',phone:'',address:'',governorate:'',area:'',delivery_date:'',notes:'',delivery_notes:'',...parsed.fields,invoice_date:'',delivery_fee:parsed.fields.delivery_fee??'',discount:parsed.fields.discount??'',items:parsed.items.length?parsed.items:[{name:'',quantity:'',unit:'',unit_price:''}],source_intake:{...parsed,extraction_mode:'mock',reviewed:false}};extractionStatus='محاكاة محلية لاختبار الربط فقط، ليست نتيجة مزود ذكاء اصطناعي.';dirty=true;drawEditor()}catch(e){extractionStatus='تعذر اختبار الترتيب. الأصل والمراجعة محفوظان. '+e.message;if($('extraction-status'))$('extraction-status').textContent=extractionStatus;toast(e.message,true)}}
async function saveDraft(submit=false){readEditor();if(submit&&editor.payload.source_intake?.version===2)assertQuoteCompatibility(editor.payload);if(($('raw-message').value.trim()||editor.payload.source_intake)&&$('raw-message').value!==editor.payload.source_intake?.raw_text)throw Error('رتب الرسالة بعد آخر تعديل حتى نحفظ الأصل الصحيح مع المسودة');if(submit&&editor.payload.source_intake&&!editor.payload.source_intake.reviewed)throw Error('أكد مراجعة النص الأصلي والسطور المتبقية أولًا');if(submit&&!$('invoice-editor').reportValidity())return;const p=editor.payload;if(submit&&!normalizePhone(p.phone))throw new Error('راجع رقم الموبايل كاملًا');const saved=await api('draft_save',{...(editor.id?{id:editor.id,version:editor.version}:{}),payload:p});editor={...saved};dirty=false;await refresh();if(submit){await api('submit',{id:saved.id,version:saved.version});await refresh();routeTo('review/'+saved.id)}else{toast('اتحفظت المسودة فقط، من غير ترحيل للحسابات');drawEditor()}}
async function loadDraft(id){const requestedHash=location.hash;const d=await api('draft_get',{id});if(location.hash!==requestedHash)return;if(!d)throw new Error('المسودة غير موجودة');if(d.state==='approved'){toast('المسودة دي اتعمدت، افتح الفاتورة من سجل الفواتير');routeTo('invoices');return}editor=structuredClone(d);dirty=false;drawEditor()}
async function reviewPage(id){const requestedHash=location.hash;const resolved=await api('draft_review',{id});if(location.hash!==requestedHash)return;review=resolved;const p=review.calculated;html(`<a class="back" href="#draft/${id}">رجوع للتعديل ←</a><h1>راجع كل التفاصيل</h1><div class="steps"><span>١. العميل والأصناف</span><span class="active">٢. مراجعة كاملة</span><span>٣. اعتماد وإرسال</span></div>${notice('هذه مسودة غير معتمدة. التاريخ المستخدم في الحسابات: <b>'+esc(dateLabel(p.invoice_date))+'</b>. لو أي بند اتغير، يلزم مراجعة واعتماد جديد.')}<div class="row wrap">${badge(review.state)}<span class="muted">نسخة المراجعة ${review.version}</span></div>${paper(p,{draft:true})}<div class="card"><div class="check"><input id="approval-confirm" type="checkbox"><label for="approval-confirm">أنا حمدي، راجعت العميل والعنوان والتاريخ والأصناف والكميات والأسعار والإجمالي، وأوافق على اعتماد هذه النسخة وترحيلها للحسابات.</label></div>${me.role==='owner'?`<div class="actions"><button class="primary" data-action="approve">اعتماد وحفظ وترحيل للحسابات</button><button class="danger" data-action="reject">رفض وإرجاع المسودة</button></div>`:notice('المراجعة متاحة للفريق. الاعتماد النهائي لحمدي فقط.')}<div class="actions"><button class="secondary" data-action="edit-review">تعديل المسودة</button><button class="plain" data-action="print-review">طباعة مسودة موسومة</button></div></div>`)}
function invoices(initialState='all'){html(title('كل الفواتير','النسخة النهائية محفوظة بتاريخها، والمسودات منفصلة عنها.')+`<div class="searchrow"><input id="invoice-search" placeholder="رقم الفاتورة، الاسم، الهاتف أو المنطقة" aria-label="بحث الفواتير"><select id="invoice-state" aria-label="حالة الفاتورة"><option value="all">جميع الحالات</option>${statuses.map(s=>`<option value="${s}">${({draft:'مسودة',review:'تحت المراجعة',approved:'معتمدة',sent:'مرسلة',cancelled:'ملغاة'})[s]}</option>`).join('')}</select><input id="invoice-date" type="date" aria-label="تاريخ الفاتورة"></div><div id="invoice-results"></div>`);invoicePageNo=0;$('invoice-state').value=initialState;renderInvoices().catch(e=>toast(e.message,true));bindListSearch(['invoice-search','invoice-state','invoice-date'],'invoices',async()=>{if(!$('invoice-search'))return;invoicePageNo=0;await renderInvoices()})}
async function renderInvoices(){const request=++invoiceRequest;const result=await api('invoice_list',{page:invoicePageNo,query:$('invoice-search').value,state:$('invoice-state').value,date:$('invoice-date').value});if(request!==invoiceRequest||!$('invoice-results'))return;$('invoice-results').innerHTML=(result.rows.map(x=>x.kind==='draft'?draftCard(x):invoiceCard(x)).join('')||empty('لا توجد نتائج'))+pager(result,'invoices')}
async function invoicePage(id){const requestedHash=location.hash;const resolved=await api('invoice_get',{id});if(location.hash!==requestedHash)return;currentInvoice=resolved;if(!currentInvoice)throw new Error('الفاتورة غير موجودة');const i=currentInvoice;html(`<a class="back" href="#invoices">الفواتير ←</a><div class="screen-title"><div><h1>${esc(i.invoice_number)}</h1><p class="muted">النسخة ${i.version} · تاريخ الحسابات ${esc(dateLabel(i.accounting_date))}</p></div>${badge(i.state)}</div>${notice(i.state==='cancelled'?'الفاتورة ملغاة، محفوظة للتاريخ ولا يمكن مشاركة رابطها.':'اتحفظت في سجل الحسابات المرتبط. أي تعديل يرجع للمراجعة والاعتماد أولًا.')}<div class="wide-actions"><button class="primary" data-action="copy-invoice">نسخ نص الفاتورة</button><button class="secondary" data-action="image-invoice">تنزيل صورة</button><button class="secondary" data-action="print-invoice">طباعة / PDF</button>${i.state!=='cancelled'&&me.role!=='viewer'?`<button class="secondary" data-action="share-link">إنشاء رابط خاص</button><button class="secondary" data-action="native-share">مشاركة نص الفاتورة</button><button class="plain" data-action="confirm-sent">تأكيد إتمام الإرسال</button>`:''}</div>${paper(i)}<div class="actions">${me.role!=='viewer'&&i.state!=='cancelled'?'<button class="secondary" data-action="revise">طلب تعديل نسخة معتمدة</button>':''}${me.role==='owner'&&i.state!=='cancelled'?'<button class="danger" data-action="cancel-invoice">إلغاء موثق</button><button class="plain" data-action="revoke-links">إلغاء الروابط الخاصة</button>':''}<button class="plain" data-action="history">سجل التعديلات والإرسال</button></div>`)}
function reports(){html(title('التقارير','الفواتير المعتمدة والمرسلة فقط. المسودات والملغاة خارج إجمالي المبيعات.')+`<div class="grid"><div><label for="report-from">من تاريخ</label><input id="report-from" type="date"></div><div><label for="report-to">إلى تاريخ</label><input id="report-to" type="date"></div></div><div id="report-output"></div>`);$('report-from').onchange=$('report-to').onchange=renderReport;renderReport()}
async function renderReport(){const request=++reportRequest;try{const t=await api('report',{from:$('report-from').value,to:$('report-to').value});if(request!==reportRequest||!$('report-output'))return;$('report-output').innerHTML=`<div class="stats">${[['الفواتير',t.invoices],['العملاء',t.customers],['قيمة الفواتير',money(t.total)],['العملاء المميزون في الفترة',t.vip]].map(([k,v])=>`<div class="stat"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><section class="card"><h2>حسب المنطقة</h2>${t.areas.map(a=>`<div class="row"><span>${esc(a.area)} · ${a.n} فاتورة</span><b>${money(a.total)}</b></div>`).join('')||'<p class="muted">لا يوجد نشاط في الفترة.</p>'}</section><button class="secondary" data-action="export-report">تصدير تقرير CSV</button><p class="muted">التصدير حتى ٥٠٠٠ فاتورة في الملف. لو الفترة أكبر، اختر فترة أصغر. الملخص أعلاه يشمل كل النتائج.</p>`}catch(e){if(request===reportRequest&&$('report-output'))$('report-output').innerHTML=empty('تعذر عرض التقرير',e.message)}}

function more(){html(title('إدارة النظام','الصلاحيات والنسخ الاحتياطي ومراجعة البيانات القديمة.')+`<div class="grid"><a class="button card" href="#reports">التقارير</a><a class="button card" href="#invoices">الفواتير والحالات</a>${me.role==='owner'?'<button class="card" data-action="team">المستخدمون والصلاحيات</button><button class="card" data-action="backup">تنزيل نسخة احتياطية خاصة</button><button class="card" data-action="imports">مراجعة وربط السجل القديم</button>':''}<button class="card" data-action="install">تثبيت التطبيق على الهاتف</button></div>${notice('لا يتم استيراد أو دمج أو إعادة ترحيل أي سجل قديم تلقائيًا. النسخ الاحتياطية تحتوي على بيانات خاصة، احتفظ بها في مكان آمن.')}<div class="card"><h2>حالة البيئة</h2><p>${localMode?'قاعدة اختبار محلية معزولة. لا توجد صلة ببيانات المشروع.':'مشروع الحسابات الحالي. لا تستخدم النسخة قبل اعتماد تطبيق مخطط القاعدة واختبارات الإنتاج.'}</p><p class="muted">أساس التاريخ: التاريخ اليدوي الذي حدده حمدي. لا تاريخ افتراضي.</p><p class="muted">بداية الربط: ${me.settings?.go_live_date?esc(dateLabel(me.settings.go_live_date)):'لم تعتمد بعد، الترحيل النهائي موقوف'}</p></div>`)}
async function showLogin(){me=null;clearOffers();if($('dialog-body').querySelector('.offer-review')){$('dialog').close();$('dialog-body').innerHTML=''}$('navigation').hidden=true;$('session-controls').innerHTML='';html(`<div class="login"><div class="eyebrow">ع الحلة · دخول الفريق</div><h1>أهلاً بيك</h1><p class="muted">العملاء لا يحتاجون حسابًا. هذه اللوحة للفريق المصرح له فقط.</p><form id="login-form" class="card"><label for="login-email">البريد الإلكتروني</label><input id="login-email" type="email" autocomplete="username" required><label for="login-password">كلمة المرور</label><input id="login-password" type="password" autocomplete="current-password" required><button class="primary full" type="submit">دخول آمن</button><p class="muted">لا تنشئ هذه الصفحة حسابًا أو تغير كلمة المرور. يضيف المالك صلاحية الحساب أولًا.</p></form></div>`);$('login-form').onsubmit=async e=>{e.preventDefault();await safely(async()=>{await login($('login-email').value.trim(),$('login-password').value);$('login-password').value='';await boot()})}}
async function boot(){if(localMode){$('local-banner').hidden=false;document.title='تجربة محلية | ع الحلة'}if(!hasSession())return showLogin();try{me=await api('session');await route()}catch(e){html(`<div class="card error-box"><h1>التشغيل مش جاهز في هذه البيئة</h1><p>${esc(e.message)}</p>${notice('لن ننشئ بيانات أو نفتح صلاحيات تلقائيًا. مخطط القاعدة يحتاج اعتماد تطبيقه واختبار صلاحيات المالك.')}<button class="secondary" data-action="logout">رجوع للدخول</button></div>`)}}
async function route(){if(!me)return;nav();const requestedHash=location.hash;const [page,id]=location.hash.slice(1).split('/');++customerRequest;++invoiceRequest;++reportRequest;html(empty('جارٍ التحميل...'));try{if(me.role==='owner'){try{await loadOffers()}catch(e){/* Existing invoice screens remain available if suggestions fail. */}if(!me||location.hash!==requestedHash)return}if(!page||page==='dashboard'){await refresh();if(location.hash!==requestedHash)return;dashboard()}else if(page==='customers'){if(me.role==='owner'&&id!=='registered')await mountOffers($('content'));else customers()}else if(page==='customer')await customerPage(decodeURIComponent(id));else if(page==='new'){if(me.role==='viewer')throw new Error('صلاحية مشاهدة فقط');newEditor();if(id==='manual'){editor.editorView='manual';drawEditor()}}else if(page==='draft'){if(me.role==='viewer')throw new Error('صلاحية مشاهدة فقط');await loadDraft(id)}else if(page==='review'){if(me.role==='viewer')throw new Error('صلاحية مشاهدة فقط');await reviewPage(id)}else if(page==='invoices')invoices(id||'all');else if(page==='invoice')await invoicePage(id);else if(page==='reports')reports();else more();$('content').scrollTo(0,0);window.scrollTo(0,0)}catch(e){if(location.hash!==requestedHash)return;toast(e.message,true);html(empty('تعذر فتح الصفحة',e.message))}}
async function safely(fn){if(busy)return;busy=true;const buttons=[...document.querySelectorAll('button')].map(b=>[b,b.disabled]);buttons.forEach(([b])=>b.disabled=true);try{await fn()}catch(e){toast(e.message,true)}finally{busy=false;buttons.forEach(([b,disabled])=>b.disabled=disabled)}}
async function eventFor(type){if(currentInvoice&&me.role!=='viewer'&&currentInvoice.state!=='cancelled')await api('event',{id:currentInvoice.id,event:type})}
$('content').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;await safely(async()=>{if(b.dataset.offerNumber){if(me.role!=='owner')throw new Error('للمالك فقط');showOffer(b.dataset.offerNumber,dialog);return}if(b.dataset.pageKey){const n=Number(b.dataset.page),key=b.dataset.pageKey;if(key==='customers'){customerPageNo=n;await renderCustomers()}else if(key==='invoices'){invoicePageNo=n;await renderInvoices()}else if(key==='customer-invoices'){customerInvoicesPage=n;const result=await api('invoice_list',{phone:customerCurrent.phone,page:n});$('customer-invoice-results').innerHTML=result.rows.map(x=>x.kind==='draft'?draftCard(x):invoiceCard(x)).join('')+pager(result,key)}else if(key==='customer-legacy'){customerLegacyPage=n;const result=await api('legacy_customer',{phone:customerCurrent.phone,page:n});$('customer-legacy-results').innerHTML=result.rows.map(l=>`<article class="card"><b>طلب مصدر ${esc(l.source_id)}</b><p>${esc(dateLabel(l.source_date))} · ${money(l.recorded_total)}</p><p class="muted">سجل تاريخي مراجع، ليس فاتورة جديدة ولا ترحيل مبيعات إضافي.</p></article>`).join('')+pager(result,key)}return}if(b.dataset.customer){routeTo('customer/'+encodeURIComponent(b.dataset.customer));return}if(b.dataset.invoice){routeTo('invoice/'+b.dataset.invoice);return}if(b.dataset.draft){routeTo('draft/'+b.dataset.draft);return}if(b.dataset.review){routeTo('review/'+b.dataset.review);return}if(b.dataset.removeLine!==undefined){readEditor();invalidateExtraction();editor.payload.items.splice(Number(b.dataset.removeLine),1);dirty=true;drawEditor();return}if(b.dataset.newFor){const c=(await api('customer_detail',{phone:b.dataset.newFor})).customer;dirty=false;history.pushState(null,'','#new');nav();newEditor({name:c.full_name,phone:c.phone,address:c.address,governorate:c.governorate,area:c.area,delivery_notes:c.delivery_notes});return}if(b.dataset.editCustomer){customerForm((await api('customer_detail',{phone:b.dataset.editCustomer})).customer);return}if(b.dataset.extraPhone){const p=prompt('اكتب رقم الموبايل الإضافي الكامل. لن يدمج النظام عميلين.');if(!p)return;if(!confirm('تؤكد أن هذا رقم إضافي لنفس العميل؟'))return;await api('phone_add',{phone:p,customer_phone:b.dataset.extraPhone,confirmed:true});toast('اتربط الرقم بعد التأكيد');await route();return}const action=b.dataset.action;if(action==='logout'){me=null;clearOffers();await logout();location.hash='';return showLogin()}if(action==='new-customer')return customerForm();if(action==='quick-find'){const p=normalizePhone($('quick-phone').value);if(!p)throw new Error('راجع رقم الموبايل');const d=await api('customer_detail',{phone:p});if(d.customer)routeTo('customer/'+encodeURIComponent(d.customer.phone));else toast('الرقم غير مسجل، تقدر تضيف عميل جديد');return}if(action==='lookup-customer'){readEditor();const ph=normalizePhone(editor.payload.phone);if(!ph)throw new Error('راجع الرقم');const d=await api('customer_detail',{phone:ph});if(!d.customer){toast('رقم جديد. راجع باقي بيانات العميل');return}if(!confirm('الرقم موجود. تستخدم بيانات ملف العميل السابق؟'))return;const c=d.customer;editor.payload={...editor.payload,name:c.full_name,phone:c.phone,address:c.address,governorate:c.governorate,area:c.area,delivery_notes:c.delivery_notes};drawEditor();return}if(action==='save-draft')return saveDraft();if(action==='edit-review')return routeTo('draft/'+review.id);if(action==='print-review')return printInvoice(review.calculated,{draft:true});if(action==='approve'){if(!$('approval-confirm').checked)throw new Error('أكد مراجعة هذه النسخة أولًا');if(!confirm('اعتماد نهائي وترحيل نفس النسخة للحسابات؟'))return;const key='pending-invoice-'+review.id+'-'+review.version;let requestId=sessionStorage.getItem(key);if(!requestId){requestId=crypto.randomUUID();sessionStorage.setItem(key,requestId)}const i=await api('approve',{id:review.id,version:review.version,review_hash:review.review_hash,request_id:requestId,confirmed:true});sessionStorage.removeItem(key);await refresh();routeTo('invoice/'+i.id);toast('اتعمدت الفاتورة واتحفظت في سجل الحسابات مرة واحدة');return}if(action==='reject'){const reason=prompt('سبب رفض المسودة');if(reason===null)return;await api('reject',{id:review.id,version:review.version,reason});await refresh();routeTo('invoices');toast('المسودة مرفوضة. لم ترحل للحسابات');return}if(action==='copy-invoice'){await copyText(invoiceText(currentInvoice));toast('اتنسخ نص الفاتورة، جاهز للصق في واتساب');await eventFor('copied');return}if(action==='image-invoice'){await saveImages(currentInvoice);toast('اتجهزت صورة الفاتورة للتنزيل');await eventFor('image_downloaded');return}if(action==='print-invoice')return printInvoice(currentInvoice);if(action==='native-share'){if(navigator.share){await navigator.share({title:'فاتورة '+currentInvoice.invoice_number,text:invoiceText(currentInvoice)});toast('اتفتحت المشاركة. أكد الإرسال فقط بعد إتمامه بالفعل.')}else{await copyText(invoiceText(currentInvoice));toast('اتنسخ النص، الصقه في واتساب')}return}if(action==='share-link'){const l=await api('share_create',{id:currentInvoice.id});const u=new URL('./view.html',location.href);u.hash=l.token;if(localMode)u.search='?local=1';dialog(`<h2>رابط خاص للفاتورة المعتمدة</h2>${notice('أي شخص معه الرابط يقدر يشوف هذه الفاتورة فقط. ينتهي بعد ٣٠ يومًا، ويمكن إلغاؤه.')}<textarea id="private-link" readonly dir="ltr">${esc(u.href)}</textarea><button class="primary" id="copy-private-link">نسخ الرابط</button><p class="muted">ينتهي ${esc(dateLabel(l.expires_at))}. لا يعني إنشاؤه أنه اتبعت للعميل.</p>`);$('copy-private-link').onclick=()=>safely(async()=>{await copyText(u.href);toast('اتنسخ الرابط الخاص')});return}if(action==='revoke-links'){if(!confirm('إلغاء كل الروابط الحالية لهذه الفاتورة؟'))return;await api('share_revoke',{id:currentInvoice.id});toast('اتلغت الروابط');return}if(action==='confirm-sent'){if(!confirm('تؤكد أنك أرسلت الفاتورة للعميل بالفعل؟ فتح المشاركة وحده لا يكفي.'))return;await eventFor('sent_confirmed');await refresh();await invoicePage(currentInvoice.id);toast('اتسجل تأكيد الإرسال');return}if(action==='revise'){const d=await api('revise',{id:currentInvoice.id});await refresh();routeTo('draft/'+d.id);return}if(action==='cancel-invoice'){const reason=prompt('سبب الإلغاء، لن تمحى الفاتورة أو تاريخها:');if(!reason)return;if(!confirm('إلغاء موثق وتصفير قيمة سجلها المرتبط في الحسابات؟'))return;await api('cancel',{id:currentInvoice.id,version:currentInvoice.version,reason,confirmed:true});await refresh();await invoicePage(currentInvoice.id);toast('اتلغت الفاتورة مع حفظ التاريخ');return}if(action==='history'){const h=await api('history',{id:currentInvoice.id});dialog(`<h2>سجل التعديلات والإرسال</h2>${[...(h.audit||[]),...(h.events||[])].sort((a,b)=>b.created_at.localeCompare(a.created_at)).map(x=>`<div class="history-entry"><b>${esc(({approved_and_posted:'اعتماد وترحيل للحسابات',revision_started:'بدء مراجعة تعديل',cancelled:'إلغاء موثق',copied:'نسخ النص',image_downloaded:'تنزيل صورة',link_created:'إنشاء رابط خاص',sent_confirmed:'تأكيد الإرسال',links_revoked:'إلغاء الروابط'})[x.action||x.event]||x.action||x.event)}</b><p class="muted">${esc(new Date(x.created_at).toLocaleString('ar-EG'))}<br>حساب المنفذ: <bdi>${esc(x.actor)}</bdi></p></div>`).join('')||'<p>لا يوجد سجل.</p>'}`);return}if(action==='backup'){if(!confirm('الملف يحتوي على بيانات العملاء الخاصة. تحفظه في مكان آمن؟'))return;const backup=await api('backup');download(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),'alhella-invoices-private-backup.json');toast('اتجهزت النسخة الاحتياطية الخاصة');return}if(action==='team')return teamPanel({dialog,toast});if(action==='imports')return importsPanel({dialog,toast,onChange:refresh});if(action==='install'){if(window.installPrompt){window.installPrompt.prompt();await window.installPrompt.userChoice;window.installPrompt=null}else dialog('<h2>تثبيت التطبيق</h2><p>من قائمة المتصفح اختار «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية» إذا كان متاحًا. لو الخيار مش ظاهر، افتح الموقع من Chrome عبر اتصال آمن.</p><p class="muted">التثبيت لا يجعل بيانات العملاء متاحة من غير إنترنت، ولا يخزن الفواتير للعمل دون اتصال.</p>');return}if(action==='export-report'){const from=$('report-from').value,to=$('report-to').value;const rows=(await api('report_export',{from,to})).rows;const cell=v=>'"'+String(v??'').replace(/^[\s\x00-\x20]*[=+\-@]/,"'").replace(/"/g,'""')+'"';const csv=[['رقم الفاتورة','التاريخ','العميل','الهاتف','القيمة','الحالة'],...rows.map(x=>[x.invoice_number,x.invoice_date,x.customer_snapshot.name,x.customer_phone,x.total,x.state])].map(r=>r.map(cell).join(',')).join('\r\n');download(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'alhella-invoice-report.csv');return}})});
$('session-controls').onclick=e=>{if(e.target.closest('[data-action=logout]'))safely(async()=>{me=null;clearOffers();await logout();await showLogin()})};
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&dirty){if(!confirm('فيه تعديلات لم تُحفظ. تسيبها؟')){e.preventDefault();return}dirty=false}});
window.addEventListener('hashchange',e=>{if(dirty&&!confirm('فيه تعديلات لم تُحفظ. تسيبها؟')){history.replaceState(null,'',e.oldURL);return}dirty=false;route()});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();window.installPrompt=e});
if('serviceWorker'in navigator&&!localMode)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});
boot();
